def circular_shift(x, shift):
    s = str(x)
    n = len(s)
    if shift == 0:
        return s
    if shift == n:
        return s
    if shift > n:
        return s[::-1]
    shift = shift % n
    # shift left by shift positions:
    return s[shift:] + s[:shift]


