def anti_shuffle(s):
    words = s.split(' ')
    result_words = []
    for w in words:
        if len(w) <= 1:
            result_words.append(w)
            continue
        # Check if all letters are uppercase or all lowercase letters
        letters = [c for c in w if c.isalpha()]
        if not letters:
            # No letters, leave as is
            result_words.append(w)
            continue
        all_upper = all(c.isupper() for c in letters)
        all_lower = all(c.islower() for c in letters)
        if all_upper:
            # Sort descending by ASCII
            sorted_w = ''.join(sorted(w, reverse=True))
        else:
            # Sort ascending by ASCII
            sorted_w = ''.join(sorted(w))
        result_words.append(sorted_w)
    return ' '.join(result_words)


