def parse_nested_parens(paren_string: str) -> List[int]:
    """
    Input: space-separated groups of valid parentheses strings.
    Output: list of integers representing the maximum nesting depth for each group.
    No loops or recursion are used; uses map and max with generator expressions.
    """
    groups = paren_string.split()

    def max_depth(s: str) -> int:
        # Using accumulate and max: track depth by adding +1 for '(' and -1 for ')'
        from itertools import accumulate

        # Map each char to +1 or -1
        depths = accumulate(map(lambda c: 1 if c == '(' else -1, s))
        return max(depths) if s else 0

    return list(map(max_depth, groups))


