def parse_music(music_string: str) -> Tuple[List[int], str]:
    # Hardcoded mapping from note string to its beats
    beats_map = {
        'o': 4,
        'o|': 2,
        '.|': 1
    }

    # If input is empty or only spaces, return empty list and empty string
    if not music_string.strip():
        return [], ''

    # Split notes by space (no loops allowed, so we do this directly)
    notes = music_string.split()

    # Map notes to beats without loops using map and list:
    beats = list(map(beats_map.get, notes))

    # Count occurrences of notes by first letter using str.count (no loops)
    # We count 'o' group as notes starting with 'o' (both 'o' and 'o|')
    # and '.' group as notes starting with '.'
    # Counting how many notes start with 'o' and '.' respectively:
    # Since each note is separated by space, and each note starts with either 'o' or '.',
    # we can count occurrences by counting number of notes starting with 'o' or '.'
    # without loops by using list comprehensions is not allowed, but we can count substrings:

    # Counting occurrences of notes starting with 'o':
    # We count how many notes start with 'o' by counting how many times 'o' appears at the start of a note.
    # Each note starts at positions where there's a space or at position 0.
    # So we can count occurrences of ' o' and also check if first char is 'o'.
    o_count = music_string.count(' o') + (1 if music_string.startswith('o') else 0)
    dot_count = music_string.count(' .') + (1 if music_string.startswith('.') else 0)

    # Determine the most common note group
    # If tie, choose the note with longer beat (o=4 vs .=1)
    if o_count > dot_count:
        most_common = 'o'
    elif dot_count > o_count:
        most_common = '.'
    else:
        # Tie or no notes (if no notes, return empty string)
        most_common = 'o' if o_count > 0 else ''

    return beats, most_common


