from collections import Counter

def search(lst):
    # Count frequencies
    freq = Counter(lst)
    # Filter items that satisfy frequency >= value (for ints)
    # For strings, since freq >= value doesn't make sense, we consider their natural ordering.
    # According to examples, strings should be returned as is if no numeric match is found.
    # So we find all integers satisfying freq[x] >= x and pick the max.
    # If none, return -1 if list contains ints, else return max element (string) if strings only.

    # Separate integers and strings
    ints = [x for x in freq if isinstance(x, int) and x > 0 and freq[x] >= x]
    if ints:
        return max(ints)
    # If no such int, check if list contains strings and return max string
    strings = [x for x in freq if isinstance(x, str)]
    if strings:
        return max(strings)
    return -1


