def total_match(lst1, lst2):
    def total_digits(lst):
        return sum(len(str(abs(x))) for x in lst if isinstance(x, int))

    def longest_str(lst):
        strings = [s for s in lst if isinstance(s, str)]
        if not strings:
            return None
        return max(strings, key=len)

    longest1 = longest_str(lst1)
    longest2 = longest_str(lst2)
    if longest1 is not None or longest2 is not None:
        candidates = [s for s in (longest1, longest2) if s is not None]
        # Return the longest string among candidates
        return max(candidates, key=len)

    td1 = total_digits(lst1)
    td2 = total_digits(lst2)

    chosen = lst1 if td1 <= td2 else lst2

    # Sort ascending by int values, keep original order for equal values,
    # place non-int elements at the end in original order
    # key for int: (value, original_index)
    # key for non-int: (float('inf'), original_index)

    # enumerate chosen to keep original indices
    indexed = list(enumerate(chosen))
    sorted_elements = sorted(
        indexed,
        key=lambda x: (x[1] if isinstance(x[1], int) else float('inf'), x[0])
    )

    result = [str(x[1]) for x in sorted_elements]

    return ' '.join(result)


