def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)

    def is_non_decreasing(a):
        return all(a[i] <= a[i+1] for i in range(len(a)-1))

    def shifted(arr, k):
        return arr[-k:] + arr[:-k]

    # Since the list has unique elements, if it's a rotated sorted array,
    # there will be exactly one place where arr[i] > arr[i+1].
    # The number of right shifts needed to sort it is equal to the index of that "break" + 1.
    # We'll find that break point using recursion without loops.

    def find_break(i=0):
        if i == n - 1:
            return -1
        if arr[i] > arr[i + 1]:
            return i
        return find_break(i + 1)

    break_idx = find_break()

    if break_idx == -1:
        # Already sorted, 0 shifts needed
        return 0

    # Number of right shifts needed to bring arr[break_idx+1] to front:
    shifts = n - (break_idx + 1)

    # Check if the shifted array is sorted
