def select_words(s, n):
    if not s:
        return []
    vowels = set('aeiouAEIOU')
    words = s.split()

    def consonant_count(word):
        return sum(c.isalpha() and c not in vowels for c in word)

    filtered = list(filter(lambda w: consonant_count(w) == n, words))
    filtered_sorted = sorted(filtered)
    # Preserve the original order but only for words in filtered_sorted
    result = [w for w in words if w in filtered_sorted]
    return result


