def maximum(arr, k):
    # Find the k largest elements without using built-in sort.
    # Since time complexity O(1) is impossible for this problem realistically,
    # we interpret it as "do not use built-in sorting".
    # We can use a selection algorithm or heap approach.
    # But since k <= len(arr) and arr length <= 1000, a simple selection is fine.

    if k == 0:
        return []

    # Find the k largest elements by selecting max k times
    # But this is O(k*n), acceptable given constraints and no built-in sort.
    # Instead, we can find the k-th largest element, then collect all >= that,
    # then if more than k elements are >= threshold, we select exactly k largest duplicates.
    # Let's implement a quickselect to find the kth largest element.

    def quickselect(nums, k):
        # Find kth largest element (1-based)
        # kth largest means kth from the end after sorting ascending
        def partition(left, right, pivot_index):
            pivot_value = nums[pivot_index]
            # move pivot to end
            nums[pivot_index], nums[right] = nums[right], nums[pivot_index]
            store_index = left
            for i in range(left, right):
                if nums[i] < pivot_value:
                    nums[store_index], nums[i] = nums[i], nums[store_index]
                    store_index += 1
            # move pivot to its final place
            nums[right], nums[store_index] = nums[store_index], nums[right]
            return store_index

        def select(left, right, k_smallest):
            # returns the k_smallest-th smallest element of nums within left..right
            if left == right:
                return nums[left]
            pivot_index = (left + right) // 2
            pivot_index = partition(left, right, pivot_index)
            if k_smallest == pivot_index:
                return nums[k_smallest]
            elif k_smallest < pivot_index:
                return select(left, pivot_index - 1, k_smallest)
            else:
                return select(pivot_index + 1, right, k_smallest)

        n = len(nums)
        # kth largest = (n-k)th smallest
        return select(0, n - 1, n - k)

    arr_copy = arr[:]
    threshold = quickselect(arr_copy, k)

    # Collect all elements greater than threshold
    greater = [x for x in arr if x > threshold]
    # Count how many elements equal to threshold we need
    needed = k - len(greater)
    equal = [x for x in arr if x == threshold][:needed]

    result = greater + equal

    # Now sort result in ascending order without built-in sort
    # Implement insertion sort (stable and simple)
    for i in range(1, len(result)):
        key = result[i]
        j = i - 1
        while j >= 0 and result[j] > key:
            result[j + 1] = result[j]
            j -= 1
        result[j + 1] = key

    return result


