def anti_shuffle(s):
    words = s.split(' ')
    result_words = []
    for w in words:
        if w.isalpha():
            # all letters, sort all chars
            result_words.append(''.join(sorted(w)))
        elif w.isalpha() == False and any(c.isalpha() for c in w):
            # mixed letters and punctuation: sort all chars
            result_words.append(''.join(sorted(w)))
        else:
            # all non-alpha (punctuation), sort all chars as well
            result_words.append(''.join(sorted(w)))
    return ' '.join(result_words)


