def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)
    # Find the index where the order breaks
    # i.e., arr[i] > arr[i+1]
    breaks = 0
    break_index = -1
    for i in range(n - 1):
        if arr[i] > arr[i + 1]:
            breaks += 1
            break_index = i
            if breaks > 1:
                return False

    # If no breaks, already sorted
    if breaks == 0:
        return True

    # Check if by right shifting (n - break_index - 1) times,
    # the array can be sorted.
    # This is equivalent to checking if the subarray arr[break_index+1:] + arr[:break_index+1]
    # is sorted.
    rotated = arr[break_index + 1:] + arr[:break_index + 1]
    return all(rotated[i] <= rotated[i + 1] for i in range(n - 1))


