def order_by_points(nums):
    def digit_sum(n):
        s = str(n)
        if s[0] == '-':
            # first digit after '-' is negative
            total = -int(s[1])
            for d in s[2:]:
                total += int(d)
            return total
        else:
            return sum(int(d) for d in s)
    return sorted(nums, key=lambda x: digit_sum(x))


