def move_one_ball(seq):
    if not seq:
        return True

    n = len(seq)
    # Since values are distinct, a sorted non-decreasing sequence is strictly increasing.
    # We want to check if seq can be rotated right any number of times to get a sorted sequence.
    # This is equivalent to checking if seq is a rotation of a strictly increasing sequence.

    # Count the number of "drops" where seq[i] > seq[i+1].
    drops = 0
    for i in range(n):
        if seq[i] > seq[(i+1) % n]:
            drops += 1
            if drops > 1:
                return False
    return True


