def move_one_ball(arr):
    if not arr:
        return True
    sorted_arr = sorted(arr)
    n = len(arr)
    # Check all right rotations of sorted_arr
    for i in range(n):
        rotated = sorted_arr[-i:] + sorted_arr[:-i]
        if rotated == arr:
            return True
    return False


