def anti_shuffle(s):
    import re
    def sort_word(word):
        return ''.join(sorted(word))

    # Split the string into runs of non-space and space characters, preserving all spaces
    parts = re.findall(r'\S+|\s+', s)
    result = []
    for part in parts:
        if part.isspace():
            result.append(part)
        else:
            result.append(sort_word(part))
    return ''.join(result)


