def move_one_ball(arr):
    if not arr:
        return True
    n = len(arr)
    # Count how many places the order breaks (arr[i] > arr[i+1])
    breaks = 0
    for i in range(n - 1):
        if arr[i] > arr[i + 1]:
            breaks += 1
            if breaks > 1:
                return False
    # Also check the break between last and first element (due to rotation)
    if breaks == 0:
        return True
    # If there's exactly one break, check if rotating the array can fix the order
    # The break must occur at the point where the array would be rotated.
    return arr[-1] <= arr[0]


