from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    result = []
    current_depth = 0
    max_depth = 0
    in_group = False

    for ch in paren_string:
        if ch == '(':
            in_group = True
            current_depth += 1
            if current_depth > max_depth:
                max_depth = current_depth
        elif ch == ')':
            if current_depth > 0:
                current_depth -= 1
            # else unbalanced, ignore as per standard behavior
        else:
            # Non-parenthesis char ends a group if we were in one
            if in_group:
                result.append(max_depth)
                current_depth = 0
                max_depth = 0
                in_group = False

    # If string ends while in group, append max_depth too
    if in_group:
        result.append(max_depth)

    return result


