def anti_shuffle(s):
    result = []
    word = []
    for c in s:
        if c == ' ':
            if word:
                result.append(''.join(sorted(word)))
                word = []
            result.append(' ')
        else:
            word.append(c)
    if word:
        result.append(''.join(sorted(word)))
    return ''.join(result)


