def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)
    # Find the number of places where arr[i] > arr[i+1]
    break_points = 0
    for i in range(n - 1):
        if arr[i] > arr[i + 1]:
            break_points += 1
            if break_points > 1:
                return False

    # Also check arr[n-1] > arr[0] to consider rotation
    if break_points == 0:
        # Already non-decreasing
        return True
    elif break_points == 1 and arr[-1] <= arr[0]:
        # Exactly one break point and last element <= first element means 
        # the array is sorted after some rotation (right shifts)
        return True
    else:
        return False


