def move_one_ball(arr):
    if not arr:
        return True
    n = len(arr)
    # Check if arr is a rotation of a sorted array
    # The idea: if we concatenate arr to itself, the sorted array must appear as a subarray.
    # But simpler: since rotation to right by k means arr is sorted if rotated left by n-k.
    # So we can check for the number of places where arr[i] > arr[i+1].
    # If this happens more than once, it's not a rotation of a sorted array.
    count = 0
    for i in range(n):
        if arr[i] > arr[(i+1) % n]:
            count += 1
            if count > 1:
                return False
    return True


