def select_words(s: str, n: int) -> list[str]:
    vowels = set("aeiouAEIOU")
    words = s.split()
    result = []
    for w in words:
        consonant_count = 0
        for ch in w:
            if ch.isalpha() and ch not in vowels and ch.lower() != 'y':
                consonant_count += 1
        if consonant_count == n:
            result.append(w)
    return result


