def fizz_buzz(n: int) -> int:
    count = 0
    for i in range(1, n):
        divisible_by_7 = (i % 7 == 0)
        divisible_by_11 = (i % 11 == 0)
        divisible_by_13 = (i % 13 == 0)
        if divisible_by_7 and divisible_by_11:
            count += 3
        elif divisible_by_7 or divisible_by_11 or divisible_by_13:
            count += 1
    return count


