def monotonic(nums):
    if not nums:
        return True
    non_decreasing = all(x <= y for x, y in zip(nums, nums[1:]))
    non_increasing = all(x >= y for x, y in zip(nums, nums[1:]))
    return non_decreasing or non_increasing


