def circular_shift(x: int, y: int) -> str:
    digits = list(str(x))
    n = len(digits)
    if y > n:
        # If y > number of digits, return digits reversed as string
        return ''.join(digits[::-1])
    else:
        # Shift digits circularly to the right by y positions
        y = y % n
        shifted = digits[-y:] + digits[:-y]
        return ''.join(shifted)


