def anti_shuffle(data: str) -> str:
    result = []
    i = 0
    n = len(data)
    while i < n:
        if data[i].isspace():
            # preserve all consecutive whitespace exactly
            start = i
            while i < n and data[i].isspace():
                i += 1
            result.append(data[start:i])
        else:
            # collect a non-space group
            start = i
            while i < n and not data[i].isspace():
                i += 1
            piece = data[start:i]
            sorted_piece = ''.join(sorted(piece))
            result.append(sorted_piece)
    return ''.join(result)


