def order_by_points(numbers):
    def digit_sum(n):
        s = str(n)
        total = 0
        if s[0] == '-':
            # first digit after minus sign is negative
            total += -int(s[1])
            # add the rest digits as positive
            for ch in s[2:]:
                total += int(ch)
        else:
            for ch in s:
                total += int(ch)
        return total

    return sorted(numbers, key=digit_sum)


