def circular_shift(x, shift):
    s = str(x)
    if s[0] == '-':
        sign = '-'
        digits = s[1:]
    else:
        sign = ''
        digits = s
    n = len(digits)
    if n == 0:
        return sign  # just in case x is '-' (not really an int)
    shift %= n
    shifted = digits[-shift:] + digits[:-shift] if shift else digits
    return sign + shifted


