def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)
    # Find the number of "descents" in the array
    # A descent is where arr[i] > arr[i+1]
    descents = 0
    for i in range(n - 1):
        if arr[i] > arr[i+1]:
            descents += 1
            if descents > 1:
                return False
    # Also check the wrap-around descent between last and first
    if arr[-1] > arr[0]:
        # no problem, as this is allowed in rotation
        pass
    else:
        # if no descents found in middle but last > first is false, means possible descent here
        # But since we counted descents in middle already
        # Actually this wrap-around descent counts as well
        if arr[-1] > arr[0]:
            pass
        elif arr[-1] > arr[0]:
            pass
    # But to count the wrap-around descent properly:
    if arr[-1] > arr[0]:
        # ok
        pass
    else:
        descents += 1
        if descents > 1:
            return False

    return True


