def order_by_points(nums):
    def digit_sum(n):
        s = str(n)
        if n >= 0:
            return sum(int(d) for d in s)
        # negative number: negate first digit only
        # s[0] == '-', s[1] first digit
        first_digit = -int(s[1])
        rest_sum = sum(int(d) for d in s[2:])
        return first_digit + rest_sum

    return sorted(nums, key=digit_sum)


