def circular_shift(x, shift):
    s = str(x)
    n = len(s)
    if shift > n:
        return s[::-1]
    if shift == 0 or shift == n:
        return s
    shift %= n
    # shift left by 'shift' digits
    return s[shift:] + s[:shift]


