import re

def anti_shuffle(s):
    # Split the string into tokens of words and spaces
    tokens = re.findall(r'\S+|\s+', s)
    result = []
    for token in tokens:
        if token.isspace():
            # Keep spaces as is
            result.append(token)
        else:
            # Sort characters of word in ascending order by ASCII
            sorted_word = ''.join(sorted(token))
            result.append(sorted_word)
    return ''.join(result)


