def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)

    def is_sorted_non_decreasing(a):
        return all(a[i] <= a[i+1] for i in range(len(a)-1))

    def is_sorted_non_increasing(a):
        return all(a[i] >= a[i+1] for i in range(len(a)-1))

    # Try all possible rotations by right shifting 0 to n-1 times
    # Right shift by k means last k elements come to front
    for k in range(n):
        rotated = arr[-k:] + arr[:-k]
        if is_sorted_non_decreasing(rotated) or is_sorted_non_increasing(rotated):
            return True

    return False


