def will_it_fly(q, w):
    if not q:
        return False
    total_weight = sum(q)
    if total_weight > w:
        return False
    # Check if balanced: the sum of weights on the left half equals the sum on the right half.
    n = len(q)
    mid = n // 2
    if n % 2 == 0:
        left_sum = sum(q[:mid])
        right_sum = sum(q[mid:])
    else:
        left_sum = sum(q[:mid])
        right_sum = sum(q[mid+1:])
    return left_sum == right_sum


