def order_by_points(nums):
    def digit_sum(n):
        s = str(n)
        total = 0
        # first digit sign is considered: if negative, first digit is negative
        if s[0] == '-':
            total += -int(s[1])
            for ch in s[2:]:
                total += int(ch)
        else:
            for ch in s:
                total += int(ch)
        return total

    return sorted(enumerate(nums), key=lambda x: (digit_sum(x[1]), x[0])) and [x[1] for x in sorted(enumerate(nums), key=lambda x: (digit_sum(x[1]), x[0]))]


