        left = s[:half+1]  # include middle char
        pal = left + left[:-1][::-1]
    else:
        left = s[:half]
        pal = left + left[::-1]

    if int(pal) >= num + 1:
        return int(pal)

    # If palindrome is not greater, increment the left half (including middle if odd)
    if odd:
        left_num = int(left)
        left_num += 1
        left = str(left_num)
        if len(left) > half + 1:  # overflow, e.g. 999 -> 1000
            # length increases by 1, so palindrome will be '1' + '0'*(length-1) + '1'
            return int('1' + ('0' * (length - 1)) + '1')
        pal = left + left[:-1][::-1]
    else:
        left_num = int(left)
        left_num += 1
        left = str(left_num)
        if len(left) > half:  # overflow, e.g. 99 -> 100
            return int('1' + ('0' * (length - 1)) + '1')
        pal = left + left[::-1]

    return int(pal)


