def find_solution(a, b, n):
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else "No solution"
    if a == 0:
        if n % b == 0 and n // b >= 0:
            return (0, n // b)
        else:
            return "No solution"
    if b == 0:
        if n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return "No solution"
    x = 0
    while True:
        diff = n - a * x
        if diff < 0:
            break
        if diff % b == 0:
            y = diff // b
            if y >= 0:
                return (x, y)
        x += 1
    return "No solution"


