def get_total_number_of_sequences(n, m):
    # dp[i][x] = number of sequences of length i starting with element x
    # We want sum over x in [1..m] of dp[n][x]

    # Base case: sequences of length 1: dp[1][x] = 1 for all x in [1..m]
    dp = [0] * (m + 1)
    for x in range(1, m + 1):
        dp[x] = 1

    for length in range(2, n + 1):
        new_dp = [0] * (m + 1)
        # For each possible previous element prev, next element nxt >= 2*prev
        # sum dp[length-1][prev] for all prev where nxt >= 2*prev
        # We'll process from the largest to smallest to accumulate sums efficiently
        # But here we want to compute new_dp[x]: number of sequences length i starting with x
        # Actually we need dp for sequences starting at x at position i
        # Wait, dp[i][x] = sequences of length i starting with x
        # This is complicated: better to think dp[i][x] = number of sequences length i ending with x

    # Let's redefine dp:
    # dp[i][x] = number of sequences of length i ending with element x
    # For i=1, dp[1][x] = 1 for all x in [1..m]
    # For i>1:
    # dp[i][x] = sum dp[i-1][y] for all y where y <= x//2

    # So implement this:
    dp = [0] * (m + 1)
    for x in range(1, m + 1):
        dp[x] = 1

    for length in range(2, n + 1):
        new_dp = [0] * (m + 1)
        prefix_sum = [0] * (m + 1)
        for x in range(1, m + 1):
            prefix_sum[x] = prefix_sum[x - 1] + dp[x]
        for x in range(1, m + 1):
            limit = x // 2
            new_dp[x] = prefix_sum[limit]
        dp = new_dp

    return sum(dp[1:])  # sum of dp[n][x] for x in 1..m


