def lucky_num(n):
    # Generate lucky numbers using the classic sieve of lucky numbers.
    # Step 1: Start with the list of odd numbers starting at 1 (1,3,5,7,9,...)
    # Step 2: The first lucky number is 1 (kept by definition)
    # Step 3: Remove every nums[1]-th number (nums[1] = 3), then every nums[2]-th number, etc.
    # Continue until we have at least n lucky numbers.

    # To be safe, start with a list larger than needed
    size = 2 * n * n  # heuristic for list size to ensure we get n lucky numbers
    nums = list(range(1, size * 2, 2))  # only odd numbers starting at 1

    idx = 1  # start removing with the second element in nums (index 1)
    while idx < len(nums):
        step = nums[idx]
        if step > len(nums):
            break
        # Remove every step-th number counting from 1-based index.
        # Because list is 0-based, remove elements at indices step-1, 2*step-1, 3*step-1, ...
        del nums[step - 1::step]
        idx += 1
        if len(nums) >= n and idx >= len(nums):
            break

    return nums[:n]


