def compute_Last_Digit(a: int, b: int) -> int:
    # We want the last digit of (b! / a!) = (a+1)*(a+2)*...*b

    # If b == a, the result is 1 (empty product)
    if b == a:
        return 1

    # Compute the product modulo 10 to get the last digit
    last_digit = 1
    for x in range(a + 1, b + 1):
        last_digit = (last_digit * (x % 10)) % 10
        # Once last_digit is 0, it will remain 0, so we can break early
        if last_digit == 0:
            break

    return last_digit


