def dif_Square(n: int) -> bool:
    # We want to check if there exist integers a,b such that n = a^2 - b^2.
    # Note that a^2 - b^2 = (a-b)(a+b).
    # Let x = a-b and y = a+b, then n = x*y.
    # Since a,b integers, x and y must be integers with same parity (both even or both odd),
    # because a = (x+y)/2 and b = (y-x)/2 must be integers.
    #
    # So n can be represented as difference of squares iff n can be factorized into x*y,
    # where x and y have the same parity.
    #
    # Approach:
    # For all divisors x of n, check if y = n//x is integer and if x,y have the same parity.
    # If yes, return True.
    # Also consider negative divisors, since a,b integers can be negative.
    #
    # Because n can be zero or negative:
    # - For zero: 0 = a^2 - b^2 => a^2 = b^2 => a = ±b always possible, so True.
    # - For negative n, same logic applies.

    if n == 0:
        return True

    abs_n = abs(n)
    from math import isqrt

    for x in range(1, isqrt(abs_n) + 1):
        if abs_n % x == 0:
            y = abs_n // x
            # check (x,y) and (-x,-y) pairs for parity and sign matching n
            # Actually, since n = x*y or n = (-x)*(-y), and both equal positive abs_n,
            # we need to assign signs so that x*y = n.
            # The pairs of divisors of n are:
            # (x, n//x) and (-x, -n//x)
            # We just need to check if there exists such pair with same parity and product = n.

            # check positive x,y
            if (x % 2) == (y % 2) and x * y == n:
                return True
            # check negative x,y
            if ((-x) % 2) == ((-y) % 2) and (-x) * (-y) == n:
                return True

    return False


