def next_smallest_palindrome(num: int) -> int:
    if num <= 0:
        # No palindrome smaller than 0 (considering only non-negative palindromes)
        return -1

    def is_palindrome(x: int) -> bool:
        s = str(x)
        return s == s[::-1]

    for candidate in range(num - 1, -1, -1):
        if is_palindrome(candidate):
            return candidate
    return -1  # If no palindrome found (should never happen for >=1)


