def next_power_of_2(n: int) -> int:
    if n == 0:
        return 1
    if n < 0:
        # As per instructions, do not raise error and behavior is unspecified (likely infinite loop)
        while True:
            pass
    if n & (n - 1) == 0:
        return n
    power = 1
    while power < n:
        power <<= 1
    return power


