    # Each next element >= 2 * prev element

    if n == 0:
        return 0  # no sequences of length 0

    dp = [ [0]*(m+1) for _ in range(n+1) ]
    # Base case: sequences of length 1 are all single elements 1..m
    for x in range(1, m+1):
        dp[1][x] = 1

    for length in range(2, n+1):
        for curr in range(1, m+1):
            prev_min = (curr + 1) // 2  # prev <= curr/2 means prev >= curr/2 for next element >= 2*prev
            # Actually next >= 2*prev means prev <= curr//2
            # So for current element curr, previous elements can be any prev <= curr//2

            max_prev = curr // 2
            if max_prev == 0:
                dp[length][curr] = 0
            else:
                # sum dp[length-1][prev] for prev in [1..max_prev]
                dp[length][curr] = sum(dp[length-1][1:max_prev+1])

    return sum(dp[n][1:m+1])


