def find_Max(arr, low, high):
    if low > high:
        return None
    # If the subarray has one element
    if low == high:
        return arr[low]
    # If the subarray is already sorted (not rotated)
    if arr[low] < arr[high]:
        return arr[high]
    mid = (low + high) // 2
    # Check if mid is pivot point
    if mid < high and arr[mid] > arr[mid + 1]:
        return arr[mid]
    if mid > low and arr[mid] < arr[mid - 1]:
        return arr[mid - 1]
    # Decide which side to search
    if arr[mid] >= arr[low]:
        return find_Max(arr, mid + 1, high)
    else:
        return find_Max(arr, low, mid - 1)


