def count_list(collection):
    count = 0
    # For dicts, consider values as the "inside" collections
    if isinstance(collection, dict):
        for v in collection.values():
            if isinstance(v, (list, tuple, set, dict)):
                count += 1
    # For other collections, iterate directly over elements
    elif isinstance(collection, (list, tuple, set)):
        for item in collection:
            if isinstance(item, (list, tuple, set, dict)):
                count += 1
    else:
        # If the input is not a collection, return 0
        return 0
    return count


