def lucky_num(n):
    nums = list(range(1, 2 * n * 10, 2))  # start with odd numbers, large enough range
    idx = 1
    while len(nums) < n or idx < len(nums):
        if idx >= len(nums):
            break
        step = nums[idx]
        if step > len(nums):
            break
        # Remove every step-th number starting from step-1 index
        del nums[step - 1::step]
        idx += 1
        if len(nums) >= n and idx >= len(nums):
            break
    return nums[:n]


