def get_noOfways(n: int, m: int = 2) -> int:
    """
    Calculate the number of ways to tile a 2 x n board using 2 x 1 dominoes.
    The parameter m is included for compatibility but only m=2 (domino) is supported.

    Args:
        n (int): The length of the board (2 x n).
        m (int): Tile size, must be 2 for domino tiles on 2 x n board.

    Returns:
        int: Number of ways to tile the 2 x n board.
    """
    if m != 2:
        raise ValueError("Only domino tiles of size 2 are supported for a 2 x n board.")

    if n < 0:
        return 0
    dp = [0] * (n + 1)
    dp[0] = 1
    if n >= 1:
        dp[1] = 1
    for i in range(2, n + 1):
        dp[i] = dp[i - 1] + dp[i - 2]
    return dp[n]


