def compute_Last_Digit(a: int, b: int) -> int:
    if a == b:
        return 1
    n, m = max(a, b), min(a, b)
    # Compute last digit of n! / m! = product of (m+1) * (m+2) * ... * n
    last_digit = 1
    for x in range(m + 1, n + 1):
        last_digit = (last_digit * (x % 10)) % 10
        # Once last_digit is 0, it will remain 0
        if last_digit == 0:
            break
    return last_digit


