def dif_Square(n: int) -> bool:
    # A number n can be expressed as a difference of two squares a^2 - b^2 = n
    # if and only if n is NOT congruent to 2 mod 4.
    # Proof sketch:
    # a^2 - b^2 = (a+b)(a-b)
    # Let x = a+b, y = a-b
    # Then n = x * y
    # x and y are both integers and have the same parity (both even or both odd).
    # For n to be difference of two squares, n cannot be congruent to 2 mod 4.
    return n % 4 != 2


