def zip_tuples(t1, t2):
    len1, len2 = len(t1), len(t2)
    if len1 == 0 or len2 == 0:
        # If either tuple is empty, can't cycle through its elements
        # Return empty tuple as no pairs can be formed
        return ()
    max_len = max(len1, len2)
    return tuple(
        (t1[i % len1], t2[i % len2])
        for i in range(max_len)
    )


