def next_smallest_palindrome(n: int) -> int:
    s = str(n + 1)
    length = len(s)

    def is_all_nines(s):
        return all(ch == '9' for ch in s)

    # If all 9's, next palindrome is 10..01 (length+1 digits)
    if is_all_nines(s):
        return int('1' + ('0' * (length - 1)) + '1')

    # Helper to create palindrome by mirroring left to right
    def make_palindrome(left, odd_length):
        if odd_length:
            return left + left[:-1][::-1]
        else:
            return left + left[::-1]

    odd_length = (length % 2 != 0)
    half_len = (length + 1) // 2
    left = s[:half_len]

    # Generate palindrome by mirroring left
    p = int(make_palindrome(left, odd_length))
    if p > n:
        return p

    # Increment left and mirror again
    left_int = int(left)
    left_int += 1
    left = str(left_int)
    # If length of left changed due to increment (e.g. 999 -> 1000)
    if len(left) > half_len:
        # This means palindrome length increases by 1
        return int('1' + ('0' * (length - 1)) + '1')

    p = int(make_palindrome(left, odd_length))
    return p


