def find_solution(a: int, b: int, n: int):
    # We want non-negative integers x,y satisfying a*x + b*y = n
    # If none exist, return None.
    # Approach:
    # Iterate x from 0 up to n//a (if a > 0), check if (n - a*x) divisible by b and y >= 0.
    # Handle zero or negative a,b carefully.

    # Handle trivial cases:
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None
    if a == 0:
        if b == 0:
            return None
        if n % b == 0 and n // b >= 0:
            return (0, n // b)
        else:
            return None
    if b == 0:
        if n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return None

    # To avoid infinite loops, find ranges for x:
    # If a > 0: x >= 0 and a*x <= n => x <= n//a
    # If a < 0: x >= 0 and a*x <= n means x >= 0 and a*x <= n
    #    but since a<0, a*x <= n means x >= n/a (negative if n/a negative)
    # So for a<0, x>=0 and a*x<=n means x >= 0 and x >= n/a => x >= max(0, ceil(n/a))
    # But since x must be integer, we can try all x >= 0 and check if a*x <= n.
    # But if a<0 and n/a < 0, then no x >=0 can satisfy a*x <= n.
    # Similarly for b and y.

    # We'll try x from 0 up to some upper bound:
    # To find upper bound for x: 
    # x >= 0, y = (n - a*x)/b >= 0 => n - a*x >= 0 (if b>0), or <=0 (if b<0)
    # We'll just try x from 0 up to some upper bound:
    # For positive b, y >=0 => n - a*x >= 0 => a*x <= n
    # For negative b, y >=0 => n - a*x <= 0 => a*x >= n

    # So for b>0:
    # y = (n - a*x)/b >= 0 => n - a*x >= 0 => a*x <= n
    # For a>0 and b>0: x in [0, n//a]
    # For a<0 and b>0: a*x <= n => x >= n/a but x>=0 so x in [max(0, ceil(n/a)), +inf)
    # But we cannot search infinite. 
    # Similarly for b<0.

    # To limit search, we can try all x in [0, max_x]
    # max_x can be:
    # If a>0: max_x = n//a if n>=0 else 0
    # If a<0: max_x = 0 (can't have x>0, because a*x <= n for y>=0)
    # But if a<0 and n>=0, a*x <= n means x >= n/a (negative), so no x>=0 satisfies.
    # So for a<0 and n>=0, no x>=0 satisfies a*x <= n (for b>0).

    # To cover all cases, try x in range 0 to a reasonable upper bound:
    # upper bound for x: max(0, n//a) if a>0 else 0
    # but if a<0, try x=0 only (or none)

    # Similarly for b<0 case.

    # To avoid complexity, try x in range 0 to max_x, where max_x is:
    # if a > 0: max_x = n//a if n>=0 else 0
    # if a < 0: max_x = 0
    # if a == 0: handled above

    # But if max_x < 0, try no x.

    # We'll try all x in [0..max_x], for each check if y = (n - a*x)/b is integer and >= 0.

    # If we find any, return first found.

    # If no solution found, return None

    import math

    # Helper to check if a divides b (integer division)
    def divides(d, val):
        if d == 0:
            return False
        return val % d == 0

    # Determine max_x
    if a > 0:
        max_x = n // a if n >= 0 else -1
    elif a < 0:
        # For a<0, and x >=0, a*x <= n means x >= n/a
        # Since a<0, n/a negative or positive?
        # x >= max(0, ceil(n/a))
        # But if n/a <=0, max_x = 0 (try only x=0)
        # if n/a > 0, then x >= positive number, no upper bound => infinite
        # To avoid infinite, try x in [ceil(max(0, n/a)) .. ceil(max(0, n/a)) + 1000]
        # Or better: try x in [0..1000] only
        # But since we want minimal solution, try x=0 only (safe)
        max_x = 0
    else:
        # a==0 handled above
        max_x = -1

    if max_x < 0:
        return None

    for x in range(max_x + 1):
        rem = n - a * x
        # Check if rem divisible by b and y>=0
        if b == 0:
            # Then y can only be zero if rem==0
            if rem == 0:
                y = 0
                if y >= 0:
                    return (x, y)
            continue
        if rem % b == 0:
            y = rem // b
            if y >= 0:
                return (x, y)

    # No solution found
    return None


