def find_exponentio(a, b):
    if len(a) != len(b):
        raise ValueError("Tuples must be of equal length")
    result = []
    for x, y in zip(a, b):
        pow_val = x ** y
        prod_val = x * y
        if pow_val != prod_val:
            raise ValueError(f"For elements {x} and {y}, {x}**{y} != {x}*{y}")
        result.append(pow_val)
    return tuple(result)


