def get_total_number_of_sequences(m: int, n: int) -> int:
    # Handle the edge case when sequence length is 0:
    # There is exactly one empty sequence of length 0.
    if n == 0:
        return 1

    # dp[i][v] = number of sequences of length i ending with value v
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # base case: sequences of length 1, each value 1..m
    for v in range(1, m + 1):
        dp[1][v] = 1

    for i in range(2, n + 1):
        for v in range(1, m + 1):
            total = 0
            # Previous element u must satisfy u == 2*v or v == 2*u
            if 2 * v <= m:
                total += dp[i - 1][2 * v]
            if v % 2 == 0:
                half = v // 2
                total += dp[i - 1][half]
            dp[i][v] = total

    return sum(dp[n][1:])


