def dict_depth(d):
    if not isinstance(d, dict):
        return 0
    max_depth = 1
    for v in d.values():
        if isinstance(v, dict):
            max_depth = max(max_depth, 1 + dict_depth(v))
        elif isinstance(v, (list, tuple)):
            # For lists/tuples, check if they contain dicts or nested lists/tuples with dicts
            inner_max = 0
            for item in v:
                if isinstance(item, dict) or isinstance(item, (list, tuple)):
                    inner_max = max(inner_max, dict_depth(item))
            if inner_max > 0:
                max_depth = max(max_depth, 1 + inner_max)
    return max_depth


