def smallest_missing(arr, low, high):
    # We want the smallest non-negative integer missing from the values expected at indices [low, high],
    # assuming arr[i] == i pattern (i.e. values expected are low, low+1, ..., high).
    # It's possible that the missing integer is high + 1 if all from low to high are present.
    left, right = low, high
    while left <= right:
        mid = (left + right) // 2
        # Check if arr[mid] equals mid (expected value)
        if arr[mid] == mid:
            # Missing number must be in right half
            left = mid + 1
        else:
            # Missing number is in left half (including mid)
            right = mid - 1
    # left is the smallest missing number in [low, high] index range
    return left


