import random

def permute_string(s):
    def backtrack(path, used):
        if len(path) == len(chars):
            permutations.append(''.join(path))
            return
        for i in range(len(chars)):
            if used[i]:
                continue
            used[i] = True
            path.append(chars[i])
            backtrack(path, used)
            path.pop()
            used[i] = False

    chars = list(s)
    permutations = []
    backtrack([], [False]*len(chars))
    random.shuffle(permutations)
    return permutations


