def lucky_num(n):
    numbers = list(range(1, 2 * n * 10))  # large enough range to find n lucky numbers
    index = 1
    while index < len(numbers):
        step = numbers[index]
        if step > len(numbers):
            break
        del numbers[step - 1::step]
        index += 1
        if len(numbers) >= n and index > n:  # a heuristic to stop early if list is large enough
            break
    return numbers[:n]


