def dif_Square(n: int) -> bool:
    # A number n can be represented as a difference of two squares:
    # n = a^2 - b^2 = (a+b)(a-b)
    #
    # Let x = a+b, y = a-b, then n = xy, and x and y must be integers of the same parity
    # (both odd or both even), since a = (x+y)/2 and b = (x-y)/2 must be integers.
    #
    # For n = 4k+2, no such pairs exist, so return False.
    #
    # Otherwise, True.

    return n % 4 != 2


