def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    # Special case: if num < 8, next palindrome is num+1 (since single digit palindrome)
    if num < 8:
        return num + 1

    # Helper to check if all digits are 9
    if all(ch == '9' for ch in s):
        # Next palindrome after 999...9 is 100...001
        return int('1' + ('0' * (length - 1)) + '1')

    def create_palindrome(left_half, odd_length):
        if odd_length:
            return int(left_half + left_half[-2::-1])
        else:
            return int(left_half + left_half[::-1])

    odd_length = length % 2 != 0
    left_half_end = (length + 1) // 2
    left_half = s[:left_half_end]

    palindrome = create_palindrome(left_half, odd_length)

    if palindrome > num:
        return palindrome
    else:
        # Need to increment the middle part and form palindrome again
        # Convert left_half to int, increment, then form palindrome
        incremented = str(int(left_half) + 1)

        # If incrementing left half increases length, handle separately
        if len(incremented) > len(left_half):
            # For example: 999 -> incremented left half = 1000, length increased
            # The next palindrome is 10...01 with length+1 digits
            return int('1' + ('0' * (length - 1)) + '1')
        else:
            return create_palindrome(incremented, odd_length)


