def find_solution(a, b, n):
    if b == 0:
        # If b=0, then ax = n => x = n/a if integer
        if a != 0 and n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return 'No solution'
    # Scan non-negative x upward from 0 to find y integer and non-negative
    x = 0
    while True:
        remainder = n - a * x
        if remainder < 0:
            # Since remainder decreases as x increases, no need to continue
            break
        if b != 0 and remainder % b == 0:
            y = remainder // b
            if y >= 0:
                return (x, y)
        x += 1
    return 'No solution'


