def find_Max(arr):
    if not arr:
        return None
    low, high = 0, len(arr) - 1
    # If array is not rotated (sorted ascending), max is last element
    if arr[low] < arr[high]:
        return arr[high]
    while low <= high:
        mid = (low + high) // 2
        # Check if mid is max
        if mid < high and arr[mid] > arr[mid + 1]:
            return arr[mid]
        if mid > low and arr[mid] < arr[mid - 1]:
            return arr[mid - 1]
        # Decide which side to go
        if arr[mid] >= arr[low]:
            # Left part is sorted, max must be right
            low = mid + 1
        else:
            # Right part is sorted, max must be left
            high = mid - 1
    # Fallback (should not be reached)
    return arr[0]


