def lucky_num(n):
    numbers = list(range(1, 2 * n * 10))  # start with a large enough list to ensure n lucky numbers
    idx = 1
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th number from the list, starting counting from 1
        del numbers[step - 1::step]
        idx += 1
        if len(numbers) >= n:
            # Stop early if we have enough lucky numbers
            # But we must continue removing until idx reaches len(numbers) or step > len(numbers)
            pass
    return numbers[:n]


