def dif_Square(n: int) -> bool:
    # A number n can be expressed as a difference of squares:
    # n = a² - b² = (a-b)(a+b)
    # For a > b ≥ 0, a+b and a-b are positive integers with the same parity.
    # So n can be expressed as difference of two squares if and only if n is NOT
    # congruent to 2 modulo 4.
    # Proof: difference of squares mod 4 can be 0,1 or 3 but never 2.
    return n % 4 != 2


