def find_solution(a, b, n):
    # Extended Euclidean algorithm to find x0, y0 such that a*x0 + b*y0 = gcd(a,b)
    def extended_gcd(a, b):
        if b == 0:
            return (a, 1, 0)
        g, x1, y1 = extended_gcd(b, a % b)
        x = y1
        y = x1 - (a // b) * y1
        return (g, x, y)

    g, x0, y0 = extended_gcd(abs(a), abs(b))
    if n % g != 0:
        return "No solution"

    # Scale the solution to n
    x0 *= n // g
    y0 *= n // g

    # Adjust signs according to original a, b
    if a < 0:
        x0 = -x0
    if b < 0:
        y0 = -y0

    return ('x = ', x0, ', y = ', y0)


