def get_total_number_of_sequences(m: int, n: int) -> int:
    from functools import lru_cache

    @lru_cache(None)
    def count_sequences(prev: int, length: int) -> int:
        if length == n:
            return 1
        total = 0
        start = max(1, 2 * prev) if prev != 0 else 1
        for next_val in range(start, m + 1):
            total += count_sequences(next_val, length + 1)
        return total

    return count_sequences(0, 0)


