def remove_column(data, index):
    if not isinstance(data, list):
        return data
    result = []
    for item in data:
        if isinstance(item, list):
            # Remove element at index if possible
            if 0 <= index < len(item):
                result.append(item[:index] + item[index+1:])
            else:
                result.append(item[:])  # no removal if index out of range
        elif isinstance(item, list):
            # Just in case, but won't happen since above check covers lists
            result.append(remove_column(item, index))
        else:
            # If item is not list, keep as is
            result.append(item)
    return result


