def sum_column(table, column_index):
    if not table:
        raise IndexError("Column index out of bounds for empty table")
    # Check if column_index is valid for the table structure
    max_cols = max((len(row) for row in table), default=0)
    if column_index < 0 or column_index >= max_cols:
        raise IndexError("Column index out of bounds for the table structure")

    total = 0
    for row in table:
        if len(row) > column_index:
            val = row[column_index]
            if isinstance(val, (int, float)):
                total += val
    return total


