def lucky_num(n):
    """
    Return a list of the first n lucky numbers defined by the standard lucky number sieve.
    """
    # Start with a list of odd numbers starting from 1, large enough to contain n lucky numbers
    # The lucky numbers are a subset of odd numbers, so we start with a large range of odd numbers.
    # We pick a sufficiently large initial list so that after sieving we still have at least n numbers.
    # A heuristic: since lucky numbers grow roughly like primes, start with about 5*n elements.
    size = 5 * n * 10  # generous overshoot to ensure enough lucky numbers

    numbers = list(range(1, size, 2))  # odd numbers starting from 1

    idx = 1  # index in numbers, zero-based; the second number is the first sieve step
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th number in the list, counting from index 0
        # But the counting is 1-based in the sieve definition:
        # We remove the step-th number, then 2*step-th number, etc.
        # Implementation detail: remove by indices at intervals of step, starting from step-1 index
        del numbers[step-1::step]
        idx += 1
        if len(numbers) >= n and idx >= n:
            # Once we have at least n lucky numbers and we have sieved enough steps, break early
            break

    return numbers[:n]


