def dif_Square(n: int) -> bool:
    # A number n can be expressed as a difference of two squares (x^2 - y^2)
    # if and only if n is not congruent to 2 modulo 4.
    # Equivalently: n != 2 (mod 4).
    # This is a well-known number theory result.
    # So return False if n % 4 == 2, else True.
    return n % 4 != 2


