def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)

    # Helper to check if all digits are '9'
    if all(ch == '9' for ch in s):
        # The next palindrome greater than n would be 10..01 (length+1 digits)
        return int('1' + ('0' * (length - 1)) + '1')

    # Increment n by 1 to ensure strictly greater
    n += 1
    s = str(n)
    length = len(s)

    def create_palindrome(left: str, odd_len: bool) -> int:
        if odd_len:
            return int(left + left[:-1][::-1])
        else:
            return int(left + left[::-1])

    half_len = (length + 1) // 2
    left = s[:half_len]
    odd_len = (length % 2 != 0)

    palindrome = create_palindrome(left, odd_len)
    if palindrome >= n:
        return palindrome

    # If palindrome is smaller than n, increment the left half and try again
    left_int = int(left) + 1
    left = str(left_int)
    # Adjust if length changed after increment (e.g. 999 -> 1000)
    if len(left) > half_len:
        # This happens if incrementing left increases length, e.g. 999->1000
        # In this case, palindrome length increases by 1
        length += 1
        odd_len = (length % 2 != 0)
        half_len = (length + 1) // 2
        left = '1' + ('0' * (half_len - 1))
        # palindrome will be 10..01 of new length
        return int(left + left[:-1][::-1]) if odd_len else int(left + left[::-1])
    else:
        return create_palindrome(left, odd_len)


