def find_solution(a, b, n):
    for x in range(n // a + 1 if a != 0 else 1):
        remainder = n - a * x
        if b == 0:
            if remainder == 0:
                return ('x = ', x, ', y = ', 0)
            else:
                continue
        if remainder % b == 0:
            y = remainder // b
            if y >= 0:
                return ('x = ', x, ', y = ', y)
    return 'No solution'


