def get_total_number_of_sequences(N: int, K: int) -> int:
    from functools import lru_cache

    @lru_cache(None)
    def count_sequences(start: int, length: int) -> int:
        if length == 1:
            return 1 if start <= N else 0
        total = 0
        next_min = 2 * start
        for next_val in range(next_min, N + 1):
            total += count_sequences(next_val, length - 1)
        return total

    total_sequences = 0
    for first in range(1, N + 1):
        total_sequences += count_sequences(first, K)
    return total_sequences


