def text_match(text: str) -> bool:
    pos_a = text.find('a')
    if pos_a == -1:
        return False
    pos_b = text.find('b', pos_a + 1)
    if pos_b == -1:
        return False
    pos_c = text.find('c', pos_b + 1)
    if pos_c == -1:
        return False
    return True


