def filter_data(data):
    # Extract only certain specific fields from each individual's details.
    # Since the task is ambiguous, choose a standard approach:
    # For each individual (key), extract only the details that have string or numeric values,
    # ignoring nested dicts or other types.
    # Also, ignore entries where details are not dicts.

    filtered = {}
    for name, details in data.items():
        if isinstance(details, dict):
            filtered_details = {k: v for k, v in details.items() if isinstance(v, (str, int, float, bool))}
            if filtered_details:
                filtered[name] = filtered_details
    return filtered


