def lucky_num(n):
    numbers = list(range(1, 2*n*10))  # start with a large enough range to ensure we get n lucky numbers
    i = 1
    while len(numbers) < n or i < len(numbers):
        step = numbers[i]
        if step > len(numbers):
            break
        # Remove every step-th number (1-based indexing)
        numbers = [num for idx, num in enumerate(numbers, 1) if idx % step != 0]
        i += 1
        if len(numbers) >= n and i >= len(numbers):
            break
    return numbers[:n]


