def compute_Last_Digit(a: int, b: int) -> int:
    if a > b:
        return 0
    last_digit = 1
    for x in range(a + 1, b + 1):
        last_digit = (last_digit * (x % 10)) % 10
        # If last_digit is 0, it will remain 0
        if last_digit == 0:
            break
    return last_digit


