def dif_Square(n: int) -> bool:
    # A number n can be expressed as a difference of squares:
    # n = a^2 - b^2 = (a+b)(a-b)
    # Let x = a+b and y = a-b, then n = x*y
    # Since a and b are integers, x and y must be integers of the same parity (both even or both odd)
    # Thus n must have at least one factorization n = x*y where x and y have the same parity.
    #
    # Equivalently:
    # - If n is odd, any factorization (odd * odd) works, so all odd n can be represented.
    # - If n is divisible by 4, then n = (even * even), so yes.
    # - If n is even but not divisible by 4 (i.e., n % 4 == 2), then no.
    #
    # So the condition is: n is NOT congruent to 2 mod 4.
    #
    # Examples:
    # 0 = 0^2 - 0^2, True
    # 1 = 1^2 - 0^2, True
    # 2 = no, False
    # 3 = 2^2 - 1^2 = 4-1 =3, True
    # 4 = 2^2 - 0^2, True
    #
    # This works for negative n as well since (-n) = difference of squares implies n = difference of squares by swapping a and b.

    return n % 4 != 2


