def find_Max(arr):
    if not arr:
        return None  # or raise an error if empty input not allowed
    low, high = 0, len(arr) - 1
    while low < high:
        mid = (low + high) // 2
        if arr[mid] > arr[high]:
            low = mid + 1
        else:
            high = mid
    # low is the index of the minimum element, max is the element before it (or last element if low = 0)
    return arr[low - 1] if low > 0 else arr[-1]


