def lucky_num(n):
    numbers = list(range(1, 2 * n * 10))  # Large enough range to generate n lucky numbers
    idx = 1
    while idx < len(numbers) and len(numbers) < n:
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th number starting from step-1 index
        del numbers[step - 1::step]
        idx += 1
    return numbers[:n]


