def tuple_to_set(*tuples):
    result = set()
    for t in tuples:
        result.update(t)
    return result

def get_noOfways(n: int) -> int:
    if n == 0 or n == 1:
        return 1
    dp = [0] * (n + 1)
    dp[0], dp[1] = 1, 1
    for i in range(2, n + 1):
        dp[i] = dp[i-1] + dp[i-2]
    return dp[n]


